#include <string>
#include <vector>
#include <cstdint>

// Simple Slice implementation for testing
struct Slice {
  const char* data_;
  size_t size_;
  Slice() : data_(nullptr), size_(0) {}
  Slice(const char* d, size_t s) : data_(d), size_(s) {}
  size_t size() const { return size_; }
  const char* data() const { return data_; }
  char operator[](size_t i) const { return data_[i]; }
};

// PutVarint32 implementation (simplified)
void PutVarint32(std::string* dst, uint32_t value) {
  char buf[5];
  char* ptr = buf;
  while (value >= 0x80) {
    *ptr++ = (value & 0x7F) | 0x80;
    value >>= 7;
  }
  *ptr++ = value;
  dst->append(buf, ptr - buf);
}

void BlockBuilder_Add(std::string* buffer, std::string* last_key, const Slice& key, const Slice& value, int restart_interval, int* counter, std::vector<uint32_t>* restarts) {
  // Check if we need to create a restart point
  if (*counter == restart_interval) {
    // Restart: no prefix compression
    restarts->push_back(buffer->size());
    *counter = 0;
  }

  size_t shared = 0;
  if (*counter < restart_interval) {
    // Compute shared prefix with last_key
    const size_t min_length = std::min(last_key->size(), key.size());
    while (shared < min_length && (*last_key)[shared] == key[shared]) {
      shared++;
    }
  } else {
    shared = 0;
  }

  size_t non_shared = key.size() - shared;

  // Encode entry: shared_bytes, non_shared_bytes, value_length (all varints)
  PutVarint32(buffer, static_cast<uint32_t>(shared));
  PutVarint32(buffer, static_cast<uint32_t>(non_shared));
  PutVarint32(buffer, static_cast<uint32_t>(value.size()));

  // Append key delta and value
  buffer->append(key.data() + shared, non_shared);
  buffer->append(value.data(), value.size());

  // Update last_key to current full key
  last_key->resize(shared);
  last_key->append(key.data() + shared, non_shared);

  // Increment counter
  (*counter)++;
}

